def tokens_per_month(rpm, avg_tokens):
    return rpm * avg_tokens * 60 * 24 * 30

def recommend(monthly_tokens):
    return 'PTU' if monthly_tokens >= 1_000_000_000 else 'PAYGO'

workloads = [('chatbot', 50, 800), ('batch-report', 2, 1500)]
for name, rpm, avg in workloads:
    total = tokens_per_month(rpm, avg)
    print(f'{name}: {total} tokens/month -> {recommend(total)}')
